1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import java.util.HashSet;
8	import java.util.Set;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	/**
15	 * Assigns the owner's {@code customerCode} on create, formatted {@code <REGION>-<HASH8>}
16	 * where {@code REGION} is the region code derived from the postcode (see
17	 * {@link OwnerRegion}) and {@code HASH8} is the first 8 upper-case hex characters of
18	 * SHA-256 over ({@code normalizedTelephone + lastName}) (e.g. {@code NSW-1A2B3C4D}).
19	 *
20	 * <p>Runs after the telephone has been normalized to E.164, so the hash is stable over the
21	 * stored telephone. The base code is fully determined by the owner's region and the
22	 * telephone-plus-surname hash; should it collide with an existing owner's
23	 * {@code customerCode}, {@code -<n>} is appended with the smallest {@code n} of 2 or more
24	 * that makes it unique.
25	 */
26	public class AssignOwnerCustomerCode {
27	
28	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
29	        String region = OwnerRegion.regionOf(owner);
30	        String hash8 = sha256Hex8(owner.getTelephone() + owner.getLastName());
31	        String base = region + "-" + hash8;
32	
33	        Set<String> existing = new HashSet<>();
34	        for (Owner other : ownerRepository.findAll()) {
35	            if (other.getId() != null && other.getId().equals(owner.getId())) {
36	                continue;
37	            }
38	            String code = other.getCustomerCode();
39	            if (code != null) {
40	                existing.add(code);
41	            }
42	        }
43	
44	        String code = base;
45	        for (int n = 2; existing.contains(code); n++) {
46	            code = base + "-" + n;
47	        }
48	        owner.setCustomerCode(code);
49	    }
50	
51	    /** First 8 upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code s}. */
52	    private static String sha256Hex8(String s) {
53	        try {
54	            byte[] digest = MessageDigest.getInstance("SHA-256")
55	                    .digest(s.getBytes(StandardCharsets.UTF_8));
56	            StringBuilder sb = new StringBuilder(8);
57	            for (int i = 0; i < 4; i++) { // 4 bytes -> 8 hex characters
58	                sb.append(String.format("%02X", digest[i]));
59	            }
60	            return sb.toString();
61	        }
62	        catch (NoSuchAlgorithmException e) {
63	            throw new IllegalStateException("SHA-256 not available", e);
64	        }
65	    }
66	}
