1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
24	    @Mapping(target = "initials",
25	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
26	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
27	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
28	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
29	    @Mapping(target = "locality", expression = "java(locality(owner))")
30	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
31	    @Mapping(target = "bulkSignupWarning",
32	        expression = "java(Boolean.TRUE.equals(owner.getBulkSignupWarning()))")
33	    @Mapping(target = "possibleDuplicate",
34	        expression = "java(Boolean.TRUE.equals(owner.getPossibleDuplicate()))")
35	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
36	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
37	    @Mapping(target = "telephoneDisplay",
38	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerTelephones.toDisplay(owner.getTelephone()))")
39	    @Mapping(target = "identityKey",
40	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.identityKey(owner))")
41	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
42	    OwnerDto toOwnerDto(Owner owner);
43	
44	    /**
45	     * The canonical API path to this owner, formatted {@code /api/owners/<id>}. Null
46	     * until the owner has been assigned an id.
47	     */
48	    default String selfLink(Owner owner) {
49	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
50	    }
51	
52	    /**
53	     * Derives the owner's age band from the {@code birthDate} measured against the
54	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to
55	     * 64 inclusive and {@code SENIOR} at 65 or over. Null when no birth date is present.
56	     */
57	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
58	        java.time.LocalDate birthDate = owner.getBirthDate();
59	        if (birthDate == null) {
60	            return null;
61	        }
62	        java.time.LocalDate reference = owner.getRegistrationDate() != null
63	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
64	        int years = java.time.Period.between(birthDate, reference).getYears();
65	        if (years < 18) {
66	            return OwnerDto.AgeBandEnum.MINOR;
67	        }
68	        if (years < 65) {
69	            return OwnerDto.AgeBandEnum.ADULT;
70	        }
71	        return OwnerDto.AgeBandEnum.SENIOR;
72	    }
73	
74	    /**
75	     * Composes the owner's salutation from the optional title and the last name:
76	     * {@code <title> <lastName>} when a title is present (non-null and not blank),
77	     * or just the last name when no title was supplied.
78	     */
79	    default String salutation(Owner owner) {
80	        String title = owner.getTitle();
81	        if (title != null && !title.isBlank()) {
82	            return title + " " + owner.getLastName();
83	        }
84	        return owner.getLastName();
85	    }
86	
87	    /**
88	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email
89	     * address is present (non-null and not blank), otherwise {@code PHONE}.
90	     */
91	    default String contactPreference(Owner owner) {
92	        String email = owner.getEmail();
93	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
94	    }
95	
96	    /**
97	     * Derives the owner's locality (region) from the owner's {@code customerCode}
98	     * identity ({@code <REGION>-<HASH8>}): the locality is the {@code REGION} segment
99	     * of that identity. When the customer code has not been assigned yet, it falls
100	     * back to deriving the region directly (see
101	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion}).
102	     */
103	    default String locality(Owner owner) {
104	        String region = org.springframework.samples.petclinic.rest.function.owner.OwnerRegion
105	            .regionFromCustomerCode(owner.getCustomerCode());
106	        return region != null ? region
107	            : org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.regionOf(owner);
108	    }
109	
110	    /**
111	     * Derives the owner's IANA timezone name from the owner's locality/region via the
112	     * pinned region-to-timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
113	     * QLD->Australia/Brisbane). Null when the region has no mapped timezone.
114	     */
115	    default String timezone(Owner owner) {
116	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion
117	            .timezoneOfRegion(locality(owner));
118	    }
119	
120	    /**
121	     * Derives the owner's membership number, formatted {@code <customerCode>-M<YY>}
122	     * where {@code YY} is the two-digit fiscal year of the (business-day-adjusted)
123	     * registration date (e.g. {@code NSW-1A2B3C4D-M26}). The fiscal year starts on
124	     * 1 July and is named by the calendar year it ends in. Null when either source
125	     * field is absent.
126	     */
127	    default String membershipNumber(Owner owner) {
128	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
129	            return null;
130	        }
131	        int fiscalYear = org.springframework.samples.petclinic.rest.function.owner.OwnerFiscalYear
132	            .fiscalYearOf(owner.getRegistrationDate());
133	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYear % 100);
134	    }
135	
136	    /**
137	     * Derives the owner's fiscal year, formatted {@code FY<YY>}, from the
138	     * (business-day-adjusted) registration date. The fiscal year starts on 1 July and
139	     * is named by the calendar year it ends in. Null when no registration date is set.
140	     */
141	    default String fiscalYear(Owner owner) {
142	        if (owner.getRegistrationDate() == null) {
143	            return null;
144	        }
145	        return org.springframework.samples.petclinic.rest.function.owner.OwnerFiscalYear
146	            .fiscalYearLabel(owner.getRegistrationDate());
147	    }
148	
149	    /**
150	     * Computes a single Luhn check digit (0-9) over the digits contained in the
151	     * owner's {@code customerCode}. Null when the customer code is absent.
152	     */
153	    default Integer checkDigit(Owner owner) {
154	        String customerCode = owner.getCustomerCode();
155	        if (customerCode == null) {
156	            return null;
157	        }
158	        int sum = 0;
159	        boolean dbl = true;
160	        for (int i = customerCode.length() - 1; i >= 0; i--) {
161	            char c = customerCode.charAt(i);
162	            if (c < '0' || c > '9') {
163	                continue;
164	            }
165	            int d = c - '0';
166	            if (dbl) {
167	                d *= 2;
168	                if (d > 9) {
169	                    d -= 9;
170	                }
171	            }
172	            sum += d;
173	            dbl = !dbl;
174	        }
175	        return (10 - (sum % 10)) % 10;
176	    }
177	
178	    Owner toOwner(OwnerDto ownerDto);
179	
180	    @Mapping(target = "id", ignore = true)
181	    @Mapping(target = "pets", ignore = true)
182	    Owner toOwner(OwnerFieldsDto ownerDto);
183	
184	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
185	
186	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
187	
188	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
189	        OwnerPageDto ownerPageDto = new OwnerPageDto();
190	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
191	        ownerPageDto.setPage(ownerPage.getNumber());
192	        ownerPageDto.setSize(ownerPage.getSize());
193	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
194	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
195	        return ownerPageDto;
196	    }
197	}
